If you would like to test this line, I saw this unit-test approach. However, this involves corrupting the open-ledger because it is quite unreachable through normal transaction construction.


```
        // Sole LP whose trustline balance and the AMM's LPTokenBalance disagree
        // by more than the 0.1% tolerance: withdrawal must fail, not auto-adjust.
        {
            Env env(*this, features);
            fund(env, gw_, {alice_}, XRP(1'000'000'000), {USD(1'000'000'000)});
            AMM amm(env, gw_, XRP(2), USD(1));

            // Bypasses every transaction check. Do not env.close() between here
            // and the withdraw, or the edit is discarded with the open ledger.
            env.app().getOpenLedger().modify([&](OpenView& view, beast::Journal) {
                auto const sle = view.read(keylet::amm(amm.ammID()));
                if (!sle)
                    return false;
                auto replacement = std::make_shared<SLE>(*sle);
                auto const lptBalance = replacement->getFieldAmount(sfLPTokenBalance);
                // Double the recorded supply: a 50% gap, far outside the tolerance.
                replacement->setFieldAmount(sfLPTokenBalance, lptBalance + lptBalance);
                view.rawReplace(replacement);
                return true;
            });

            amm.setClose(false);
            amm.withdrawAll(gw_, std::nullopt, Ter(tecAMM_INVALID_TOKENS));
            BEAST_EXPECT(amm.ammExists());
        }

```

